begin;
create temp table _had_note on commit drop as select id from public.areas where parking_note is not null;
update public.areas set parking_note='Park in the lot near the boat launch on South Shore Road (the South Shore side). From the lot''s southwest corner, walk straight into the woods looking for concrete slabs, then follow the trail uphill; about 20-30 minutes.' where id='wi_03_the_reserve' and id not in (select id from _had_note);
update public.areas set parking_note='Park in the lot near the boat launch on South Shore Road (the South Shore side). From the lot''s southwest corner, walk straight into the woods looking for concrete slabs, then follow the trail uphill; about 20-30 minutes.' where path <@ (select path from public.areas where id='wi_03_the_reserve') and id <> 'wi_03_the_reserve' and id not in (select id from _had_note) and parking_note is null and parking_lat is null;
update public.areas set parking_note='Park on Burma Road about 1.1 miles in from South Shore Road, by a tree on the right that still shows the scar of an old steel cable. A faint trail leads east into the woods; the boulders are about five minutes away.' where id='wi_burma_road' and id not in (select id from _had_note);
update public.areas set parking_note='Park on Burma Road about 1.1 miles in from South Shore Road, by a tree on the right that still shows the scar of an old steel cable. A faint trail leads east into the woods; the boulders are about five minutes away.' where path <@ (select path from public.areas where id='wi_burma_road') and id <> 'wi_burma_road' and id not in (select id from _had_note) and parking_note is null and parking_lat is null;
update public.areas set parking_note='Start from the Steinke Basin parking lot just off Hwy DL (on the East Bluff Woods Trail). The trail from the North Shore lot is not the right one; the other start is at the North Shore exit at Hwy DL.' where id='wi_steinke_basin' and id not in (select id from _had_note);
update public.areas set parking_note='Start from the Steinke Basin parking lot just off Hwy DL (on the East Bluff Woods Trail). The trail from the North Shore lot is not the right one; the other start is at the North Shore exit at Hwy DL.' where path <@ (select path from public.areas where id='wi_steinke_basin') and id <> 'wi_steinke_basin' and id not in (select id from _had_note) and parking_note is null and parking_lat is null;
commit;
